declare(strict_types=1);

namespace XTwitterScraper;

use XTwitterScraper\Core\Attributes\Optional;
use XTwitterScraper\Core\Attributes\Required;
use XTwitterScraper\Core\Concerns\SdkModel;
use XTwitterScraper\Core\Contracts\BaseModel;
use XTwitterScraper\SubtitleTrack\Cues;

/**
 * @phpstan-type SubtitleTrackShape = array{
 *   autoGenerated: bool,
 *   url: string,
 *   text: string,
 *   truncated: bool,
 *   cues: list<Cues|array<string,mixed>>,
 *   mediaKey?: string|null,
 *   language?: string|null,
 *   name?: string|null,
 * }
 */
final class SubtitleTrack implements BaseModel
{
    /** @use SdkModel<SubtitleTrackShape> */
    use SdkModel;

    /**
     * True when X transcribed the audio itself.
     */
    #[Required]
    public bool $autoGenerated;

    /**
     * Link to the track's first WebVTT file.
     */
    #[Required]
    public string $url;

    /**
     * Every cue's text in order, as 1 line.
     */
    #[Required]
    public string $text;

    /**
     * True when the cues cover only the start of a very long track.
     */
    #[Required]
    public bool $truncated;

    /**
     * Timed captions in order.
     *
     * @var list<Cues> $cues
     */
    #[Required(list: Cues::class)]
    public array $cues;

    /**
     * Media key of the video, as media rows carry it.
     */
    #[Optional]
    public ?string $mediaKey;

    /**
     * Language code of the track, in lower case.
     */
    #[Optional]
    public ?string $language;

    /**
     * Track name the uploader or X gave it.
     */
    #[Optional]
    public ?string $name;

    /**
     * `new SubtitleTrack()` is missing required properties by the API.
     *
     * To enforce required parameters use
     * ```
     * SubtitleTrack::with(autoGenerated: ..., url: ..., text: ..., truncated: ..., cues: ...)
     * ```
     *
     * Otherwise ensure the following setters are called
     *
     * ```
     * (new SubtitleTrack)->withAutoGenerated(...)->withUrl(...)->withText(...)->withTruncated(...)->withCues(...)
     * ```
     */
    public function __construct()
    {
        $this->initialize();
    }

    /**
     * Construct an instance from the required parameters.
     *
     * You must use named parameters to construct any parameters with a default value.
     *
     * @param list<Cues|array<string,mixed>> $cues
     */
    public static function with(bool $autoGenerated, string $url, string $text, bool $truncated, array $cues, ?string $mediaKey = null, ?string $language = null, ?string $name = null): self
    {
        $self = new self;

        $self['autoGenerated'] = $autoGenerated;
        $self['url'] = $url;
        $self['text'] = $text;
        $self['truncated'] = $truncated;
        $self['cues'] = $cues;

        null !== $mediaKey && $self['mediaKey'] = $mediaKey;
        null !== $language && $self['language'] = $language;
        null !== $name && $self['name'] = $name;

        return $self;
    }

    /**
     * True when X transcribed the audio itself.
     */
    public function withAutoGenerated(bool $autoGenerated): self
    {
        $self = clone $this;
        $self['autoGenerated'] = $autoGenerated;

        return $self;
    }

    /**
     * Link to the track's first WebVTT file.
     */
    public function withUrl(string $url): self
    {
        $self = clone $this;
        $self['url'] = $url;

        return $self;
    }

    /**
     * Every cue's text in order, as 1 line.
     */
    public function withText(string $text): self
    {
        $self = clone $this;
        $self['text'] = $text;

        return $self;
    }

    /**
     * True when the cues cover only the start of a very long track.
     */
    public function withTruncated(bool $truncated): self
    {
        $self = clone $this;
        $self['truncated'] = $truncated;

        return $self;
    }

    /**
     * Timed captions in order.
     *
     * @param list<Cues|array<string,mixed>> $cues
     */
    public function withCues(array $cues): self
    {
        $self = clone $this;
        $self['cues'] = $cues;

        return $self;
    }

    /**
     * Media key of the video, as media rows carry it.
     */
    public function withMediaKey(?string $mediaKey): self
    {
        $self = clone $this;
        $self['mediaKey'] = $mediaKey;

        return $self;
    }

    /**
     * Language code of the track, in lower case.
     */
    public function withLanguage(?string $language): self
    {
        $self = clone $this;
        $self['language'] = $language;

        return $self;
    }

    /**
     * Track name the uploader or X gave it.
     */
    public function withName(?string $name): self
    {
        $self = clone $this;
        $self['name'] = $name;

        return $self;
    }
}
